    private static PopulationWords Checked(EnemyDefinitionId enemy, EnemySpawnSettings settings, PopulationWords words) =>
        Decode(enemy, words) == settings
            ? words
            : throw new ArgumentException($"No population words give {enemy} the settings {settings}.", nameof(settings));

    private static int Bits(int word, int low, int width) => (Ensure.BetweenInclusive(0, ushort.MaxValue, word) >> low) & ((1 << width) - 1);

    private static int Place(int value, int low, int width) => Ensure.BetweenInclusive(0, (1 << width) - 1, value) << low;

    private static bool Has(int word, int bit) => (word >> bit & 1) != 0;

    private static int Signed(int word) => unchecked((short)Ensure.BetweenInclusive(0, ushort.MaxValue, word));

    private static int Half(int word) => (word & 1) == 0
        ? Ensure.BetweenInclusive(0, ushort.MaxValue, word) / 2
        : throw new InvalidDataException($"Population word ${word:X4} is not an even selector.");

    private static InvalidDataException Unmapped(string setting, int value) =>
        new($"Population words select {setting} {value}, which the species does not define.");
}
